"use client"

import React, { useState } from "react";
import { CopyIcon, RefreshCwIcon, CheckIcon, Ellipsis } from "lucide-react";

import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuTrigger } from "@/components/ui/dropdown-menu";

type GeneratedAnswer = {
  className?: string;
  GeneratedAnswer?: string;
  hours?: string;
};

const GeneratedAnswer: React.FC<GeneratedAnswer> = ({
  GeneratedAnswer,
  className,
  hours = "00:00",
}) => {
  const [copied, setCopied] = useState(false);

  const handleCopy = () => {
    if (GeneratedAnswer) {
      navigator.clipboard.writeText(GeneratedAnswer);
      setCopied(true);
      setTimeout(() => setCopied(false), 1200);
    }
  };

  const handleLike = () => {};

  const handleDisLike = () => {};

  const handleRegenerate = () => {};

  return (
    <div className="flex flex-col w-full  gap-2 max-w-lg">
      <div className={cn(" min-h-72 w-full", className)}>{GeneratedAnswer}</div>

      <div className="w-full flex justify-between items-center">
        <div>
          <span className="text-sm  text-neutral-400">{hours}</span>
        </div>

        <div className="flex gap-2">
          <Button
            className={cn(
              "bg-transparent dark:hover:bg-neutral-200/40 px-1.5 py-0.5 md:p-2 dark:bg-neutral-700/20 hover:bg-neutral-200/40 relative transition-all duration-200",
              copied && "bg-green-100 "
            )}
            onClick={handleCopy}
            title="Copier"
            disabled={copied}
          >
            <span className="flex items-center justify-center transition-all duration-200">
              {copied ? <CheckIcon className="" /> : <CopyIcon />}
            </span>
          </Button>

          <Button
            className="bg-transparent dark:hover:bg-neutral-200/40 dark:bg-neutral-700/20 hover:bg-neutral-200/40 px-1.5 py-0.5 md:p-2"
            onClick={handleLike}
            title="like GeneratedAnswer"
          >
            <svg
              xmlns="http://www.w3.org/2000/svg"
              fill="none"
              viewBox="0 0 24 24"
              strokeWidth={1.5}
              stroke="currentColor"
              className="size-6"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                d="M6.633 10.25c.806 0 1.533-.446 2.031-1.08a9.041 9.041 0 0 1 2.861-2.4c.723-.384 1.35-.956 1.653-1.715a4.498 4.498 0 0 0 .322-1.672V2.75a.75.75 0 0 1 .75-.75 2.25 2.25 0 0 1 2.25 2.25c0 1.152-.26 2.243-.723 3.218-.266.558.107 1.282.725 1.282m0 0h3.126c1.026 0 1.945.694 2.054 1.715.045.422.068.85.068 1.285a11.95 11.95 0 0 1-2.649 7.521c-.388.482-.987.729-1.605.729H13.48c-.483 0-.964-.078-1.423-.23l-3.114-1.04a4.501 4.501 0 0 0-1.423-.23H5.904m10.598-9.75H14.25M5.904 18.5c.083.205.173.405.27.602.197.4-.078.898-.523.898h-.908c-.889 0-1.713-.518-1.972-1.368a12 12 0 0 1-.521-3.507c0-1.553.295-3.036.831-4.398C3.387 9.953 4.167 9.5 5 9.5h1.053c.472 0 .745.556.5.96a8.958 8.958 0 0 0-1.302 4.665c0 1.194.232 2.333.654 3.375Z"
              />
            </svg>
          </Button>

          <Button
            className="bg-transparent dark:hover:bg-neutral-200/40  dark:bg-neutral-700/20 hover:bg-neutral-200/40 px-1.5 py-0.5 md:p-2"
            onClick={handleDisLike}
            title="like GeneratedAnswer"
          >
            <svg
              xmlns="http://www.w3.org/2000/svg"
              fill="none"
              viewBox="0 0 24 24"
              strokeWidth={1.5}
              stroke="currentColor"
              className="size-6"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                d="M7.498 15.25H4.372c-1.026 0-1.945-.694-2.054-1.715a12.137 12.137 0 0 1-.068-1.285c0-2.848.992-5.464 2.649-7.521C5.287 4.247 5.886 4 6.504 4h4.016a4.5 4.5 0 0 1 1.423.23l3.114 1.04a4.5 4.5 0 0 0 1.423.23h1.294M7.498 15.25c.618 0 .991.724.725 1.282A7.471 7.471 0 0 0 7.5 19.75 2.25 2.25 0 0 0 9.75 22a.75.75 0 0 0 .75-.75v-.633c0-.573.11-1.14.322-1.672.304-.76.93-1.33 1.653-1.715a9.04 9.04 0 0 0 2.86-2.4c.498-.634 1.226-1.08 2.032-1.08h.384m-10.253 1.5H9.7m8.075-9.75c.01.05.027.1.05.148.593 1.2.925 2.55.925 3.977 0 1.487-.36 2.89-.999 4.125m.023-8.25c-.076-.365.183-.75.575-.75h.908c.889 0 1.713.518 1.972 1.368.339 1.11.521 2.287.521 3.507 0 1.553-.295 3.036-.831 4.398-.306.774-1.086 1.227-1.918 1.227h-1.053c-.472 0-.745-.556-.5-.96a8.95 8.95 0 0 0 .303-.54"
              />
            </svg>
          </Button>

          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <Button
                className="bg-transparent dark:hover:bg-neutral-200/40 dark:bg-neutral-700/20 hover:bg-neutral-200/40 px-1.5 py-0.5 md:p-2"
                onClick={handleRegenerate}
                title="regenerate"
              >
                <RefreshCwIcon />
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent
              className={cn(
                "min-w-[12rem]",
                "border-black/10 mt-1 rounded-xl dark:border-white/10",
                "bg-neutral-100 dark:bg-neutral-900"
              )}
            >
              <DropdownMenuItem className="rounded-lg h-9 cursor-pointer hover:!bg-neutral-200 dark:hover:!bg-neutral-200/20 gap-2">
                Ajouter un commentaire
              </DropdownMenuItem>
              <DropdownMenuItem className="rounded-lg h-9 cursor-pointer hover:!bg-neutral-200 dark:hover:!bg-neutral-200/20 gap-2">
                Sans commentaire
              </DropdownMenuItem>
            </DropdownMenuContent>
          </DropdownMenu>

          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <Button
                className="bg-transparent dark:hover:bg-neutral-200/40 dark:bg-neutral-700/20 hover:bg-neutral-200/40 px-1.5 py-0.5 md:p-2"
                onClick={handleRegenerate}
                title="regenerate"
              >
                <Ellipsis />
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent
              className={cn(
                "min-w-[12rem]",
                "border-black/10 mt-1 rounded-xl dark:border-white/10",
                "bg-neutral-100 dark:bg-neutral-900"
              )}
            >
              <DropdownMenuItem className="rounded-lg h-9 cursor-pointer hover:!bg-neutral-200 dark:hover:!bg-neutral-200/20 gap-2">
                Signaler un probleme
              </DropdownMenuItem>
              <DropdownMenuItem className="rounded-lg h-9 cursor-pointer hover:!bg-neutral-200 dark:hover:!bg-neutral-200/20 gap-2">
                Exporter en PDF
              </DropdownMenuItem>
            </DropdownMenuContent>
          </DropdownMenu>
        </div>
      </div>
    </div>
  );
};

GeneratedAnswer.displayName = 'GeneratedAnswer';
export default GeneratedAnswer;

import * as React from "react";
import { Slot } from "@radix-ui/react-slot";
import { cva, type VariantProps } from "class-variance-authority";

import { cn, globalVariants } from "@/lib/utils";

const buttonVariants = cva(
  "inline-flex items-center justify-center  gap-2 whitespace-nowrap rounded-lg text-sm font-medium ring-offset-white transition-colors focus-visible:outline-hidden focus-visible:ring-2 focus-visible:ring-neutral-950 focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-50 [&_svg]:pointer-events-none [&_svg]:size-4 [&_svg]:shrink-0 dark:ring-offset-neutral-950 dark:focus-visible:ring-neutral-300 cursor-pointer",
  {
    variants: {
      variant: {
        link: "text-neutral-900 underline-offset-4 hover:underline dark:text-neutral-50",
        ...globalVariants.variant,
      },
      size: {
        default: "h-9 px-2.5 rounded-lg  py-0.5",
        sm: "h-9 rounded-lg px-3",
        lg: "h-11 rounded-lg px-8",
        icon: "h-10 w-10",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  }
);

export interface ButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement>,
    VariantProps<typeof buttonVariants> {
  asChild?: boolean;
}

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  ({ className, variant, size, asChild = false, ...props }, ref) => {
    const Comp = asChild ? Slot : "button";
    return (
      <Comp
        className={cn(buttonVariants({ variant, size }), className)}
        ref={ref}
        {...props}
      />
    );
  }
);
Button.displayName = "Button";

export { Button, buttonVariants };

import { clsx, type ClassValue } from "clsx"
import { twMerge } from "tailwind-merge"

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}

export const globalVariants = {
   variant: {
      default: "border bg-neutral-200/40 dark:bg-neutral-200/20 dark:hover:bg-neutral-200/40 text-black  dark:border-neutral-200/20  border-neutral-300/50 dark:text-neutral-200",
      ghost: "dark:hover:bg-neutral-700/40 dark:hover:bg-neutral-500/40 hover:bg-gray-200/40 bg-neutral-200/40 hover:bg-neutral-300/60 dark:bg-neutral-700 dark:text-gray-200",
      outline: "border border-neutral-300/40 dark:hover:bg-neutral-500/40 hover:bg-gray-200/40  dark:text-gray-200",
      none:"bg-none border-none",
    },
}
